import{_ as p}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/EN.P9aPnFBv.js";import{_ as u,a as g,b as l,c as f,d as v,e as b,f as y,g as w,h as x,i as A,j as k}from"./chunks/M-SNOj.BjML9gyj.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as o}from"./chunks/ON.DXVlsWbj.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as S,C as z,o as _,c as q,a3 as r,j as s,a as m,E as c,w as h}from"./chunks/framework.g9mfNVRQ.js";const W=JSON.parse('{"title":"Alarms and Alerts","description":"","frontmatter":{},"headers":[],"relativePath":"use/alarms.md","filePath":"use/alarms.md"}'),D={name:"use/alarms.md"},T={class:"admonition xdrip"},L={style:{"background-color":"dimgray",color:"white","text-align":"center"}};function E(R,i,P,N,F,C){const d=z("big");return _(),q("div",null,[i[3]||(i[3]=r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+p+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_add_alert_grey600_48dp.png" style="width:5%;"> Alarms and Alerts</p></div><p>Many alerts can be set up with xDrip.</p><p>It is recommended to enable at least three alerts if xDrip is your only glucose monitoring app:</p><ul><li>Low alert</li><li>High Alert</li><li>Missed readings alert</li></ul><h3 id="glucose-level-alerts-list" tabindex="-1">Glucose Level Alerts List <a class="header-anchor" href="#glucose-level-alerts-list" aria-label="Permalink to &quot;Glucose Level Alerts List&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Glucose Level Alerts List</p></div><p>By default, one low and one high alert are defined.</p><p>Low alerts will trigger when BG is equal to or below the alert value, high alerts when BG is equal to or above.</p><p>To create a new alert, touch the <code>CREATE LOW</code> or <code>HIGH ALERT</code> title bar.</p><p>To modify an existing alert, long touch the alert</p><div class="admonition xdrip"><p class="admonition-title">☰ Alert List</p><div style="background-color:gray;color:white;text-align:center;">  CREATE LOW ALERT </div><p><small>  Low alert       70      All day</small><br><small>Override silent mode   Default ringtone (Unknown ringtone)</small></p><div style="background-color:gray;color:white;text-align:center;">  CREATE HIGH ALERT </div><small>  High alert       224      All day</small><small>Override silent mode   Default ringtone (Unknown ringtone)</small></div><ol><li>You can name an alert the name you want, as long as no other alert has the same name</li><li>The threshold is the BG level that will trigger the alarm, only one alarm can use this value</li><li>Default snooze is the delay that will be proposed when snoozing</li><li>The alarm will trigger again every x minutes if not acknowledged</li></ol><div class="admonition xdrip"><p class="admonition-title">☰ Edit Alert</p><p>   editing low alert</p><p>  <small>Alert Name: <u>Low Alert</u></small> <span style="background-color:green;color:white;text-align:center;">1</span><br>   <small>Threshold: <u>70</u></small> <span style="background-color:green;color:white;text-align:center;">2</span><br>   <small>Default Snooze: <u>35</u></small> <span style="background-color:green;color:white;text-align:center;">3</span><br>   <small>Re-raise every x minutes: <u>1</u></small> <span style="background-color:green;color:white;text-align:center;">4</span><br>   <small>if unacknowledged</small></p><p>  <small>Alert Tone: <u>Default ringtone (unknown ringtone)</u></small> <span style="background-color:green;color:white;text-align:center;">5</span></p></div><p> 5. You can customize the alert sound: touch CHOOSE FILE to select the default ringtone for this alarm.</p><ul><li><p>System sound will allow you to choose from your phone ringtones.</p></li><li><p>Custom sound allows you to pick your sound/music.</p></li><li><p>xDrip default sound uses the app default.</p></li></ul><div class="admonition xdripitem"><p class="admonition-title">What type of sound?</p><p> System sound/Alarm<br>  Custom Sound/Alarm<br>  Default xDrip Sound</p></div><p>By default the alarm will be set up for the whole day.</p><div class="admonition xdripitem"><p class="admonition-title"><small>Select time for Alert</small></p><p>         ✅ all day</p></div><p>If you unselect the checkbox you can customize activity hours.<br> Touch the start hour and end hour to define from what time to what time the alarm will be enabled.</p><div class="admonition xdripitem"><p class="admonition-title"><small>Select time for Alert</small></p><p>         ☐ all day<br>         0:00 - 0:00</p></div><p>You can disable the alarm (uncheck) when the phone is in silent mode (disabling is not recommended)</p><div class="admonition xdripitem"><p class="admonition-title"><small>Override phone silent mode</small><span class="symbol"><small>✅</small></span></p></div><p>Force speaker will make the alarm sound on the phone even when you&#39;re using other speakers (like Bluetooth)</p><div class="admonition xdripitem"><p class="admonition-title"><small>Force Speaker</small><span class="symbol"><small>✅</small></span></p></div><p>Vibrate enables phone vibration</p><div class="admonition xdripitem"><p class="admonition-title"><small>Vibrate on alert</small><span class="symbol"><small>✅</small></span></p></div><p>Disable alert completely disables it, it will show crossed in the Alert List</p><div class="admonition xdripitem"><p class="admonition-title"><small>Disable alert</small><span class="symbol"><small>☐</small></span></p></div><p><span style="background-color:gray;color:white;"> TEST ALERT </span> will make this alert sound</p><p><span style="background-color:gray;color:white;"> SAVE ALERT </span> will save this new or modified alert</p><p><span style="background-color:gray;color:white;"> REMOVE ALERT </span> will delete this alert</p><p><span style="background-color:gray;color:white;"> SNOOZE ALERT BEFORE IT FIRES </span> will allow you to prevent the alert from triggering, for example if you already treated an expected low or a high and know BG will move anyway you can avoid hearing the alarm for the time you want.</p><h3 id="glucose-alerts-settings" tabindex="-1">Glucose Alerts Settings <a class="header-anchor" href="#glucose-alerts-settings" aria-label="Permalink to &quot;Glucose Alerts Settings&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Glucose Alerts Settings</p></div><h5 id="alert-volume-profile" tabindex="-1">Alert volume profile <a class="header-anchor" href="#alert-volume-profile" aria-label="Permalink to &quot;Alert volume profile&quot;">​</a></h5><p>You can customize the volume of your alerts</p><div class="admonition xdripitem"><p class="admonition-title">Alert volume profile</p><p> High <span style="float:right;">○ </span>   <br>  Medium <span style="float:right;">○ </span>   <br>  Ascending volume <span style="float:right;">● </span>   <br>  Vibrate only <span style="float:right;">○ </span>   <br>  Silent <span style="float:right;">○ </span>   </p></div><p>Ascending volume is recommended if you don&#39;t want the alarm to blare immediately (useful during the night). You can also <a href="#delay-ascending-volume">delay</a> ascending volume to filter noisy readings and limit the maximum volume.</p><p>Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.10.16" target="_blank" rel="noreferrer">16th Oct 2026</a>, selecting Vibrate only or Silent asks for confirmation: with these profiles alerts make no sound, even those with Override Silent Mode enabled. The profile is only changed if you confirm.</p><h5 id="audio-focus" tabindex="-1">Audio Focus <a class="header-anchor" href="#audio-focus" aria-label="Permalink to &quot;Audio Focus&quot;">​</a></h5><p>Audio Focus allows you to decide how to handle other sounds when an xDrip alarm or alert triggers.</p><div class="admonition xdripitem"><p class="admonition-title">Audio Focus</p><p>Choose what to do with other apps while playing alerts and adjusting system volume levels</p></div><p>You can automatically lower the volume, pause the other apps playing sounds (like media players) or pause all other sounds in order to better focus on xDrip sound.</p><div class="admonition xdripitem"><p class="admonition-title">Audio Focus</p><p> Don&#39;t adjust other app sounds <span style="float:right;">● </span>   <br>  Lower volume of other apps <span style="float:right;">○ </span>   <br>  Pause other apps playing audio <span style="float:right;">○ </span>   <br>  Pause all other sounds <span style="float:right;">○ </span>   </p></div><h5 id="smart-snoozing" tabindex="-1">Smart snoozing <a class="header-anchor" href="#smart-snoozing" aria-label="Permalink to &quot;Smart snoozing&quot;">​</a></h5><h5 id="smart-alerting" tabindex="-1">Smart alerting <a class="header-anchor" href="#smart-alerting" aria-label="Permalink to &quot;Smart alerting&quot;">​</a></h5><p>Smart snoozing and alerting prevent the alert from triggering or re-raising if BG is going in the right direction (upwards for low alerts and downwards for highs). The thresholds for acknowledging a sufficient change in the right direction are:</p><ul><li>Change is more than +4mg/dl in 5 minutes from low alert</li><li>Change is more than -1mg/dl in 5 minutes from high alert</li></ul><div class="admonition xdripitem"><p class="admonition-title">Smart snoozing <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Keep snoozing if glucose is heading in the right direction</p></div><div class="admonition xdripitem"><p class="admonition-title">Smart alerting <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Don&#39;t alert if glucose is heading in the right direction</p></div><h5 id="dont-alarm-during-phone-calls" tabindex="-1">Don&#39;t alarm during phone calls <a class="header-anchor" href="#dont-alarm-during-phone-calls" aria-label="Permalink to &quot;Don&#39;t alarm during phone calls&quot;">​</a></h5><p>Alarms will not sound if they trigger during a phone call.</p><div class="admonition xdripitem"><p class="admonition-title">Don&#39;t alarm during phone calls <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Alarms silenced during telephone calls</p></div><h5 id="buttons-silence-alarms" tabindex="-1">Buttons silence alarms <a class="header-anchor" href="#buttons-silence-alarms" aria-label="Permalink to &quot;Buttons silence alarms&quot;">​</a></h5><p>Buttons silence alarms is a quick way to snooze alarms by just pressing volume up or down.</p><div class="admonition xdripitem"><p class="admonition-title">Buttons silence alarms <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Pressing the volume up or down button will snooze an active alarm when in the app</p></div><h5 id="alert-buttons" tabindex="-1">Alert buttons <a class="header-anchor" href="#alert-buttons" aria-label="Permalink to &quot;Alert buttons&quot;">​</a></h5><p>Alert buttons will add an action button in the drop down view of the alert.</p><div class="admonition xdripitem"><p class="admonition-title">Alert buttons <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Show action buttons (like Snooze) within alert notifications</p></div><img src="'+u+'" style="zoom:75%;"><img src="'+g+'" style="zoom:75%;"><h5 id="start-snoozed" tabindex="-1">Start snoozed <a class="header-anchor" href="#start-snoozed" aria-label="Permalink to &quot;Start snoozed&quot;">​</a></h5><p>Start snoozed applies the snooze delay before triggering the alarm. Make sure the <code>Default snooze</code> delay is appropriate in the alarm.</p><div class="admonition xdripitem"><p class="admonition-title">Start snoozed <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Alerts start out snoozed and must persist for a while to actually trigger</p></div><h5 id="wake-screen" tabindex="-1">Wake Screen <a class="header-anchor" href="#wake-screen" aria-label="Permalink to &quot;Wake Screen&quot;">​</a></h5><p>Wake up screen during alerts.</p><div class="admonition xdripitem"><p class="admonition-title">Wake Screen<img src="'+a+'" style="zoom:75%;"></p><p> Wake up screen during alerts. Might unlock devices that don&#39;t have screen lock enabled.</p></div><h5 id="use-camera-light" tabindex="-1">Use Camera Light <a class="header-anchor" href="#use-camera-light" aria-label="Permalink to &quot;Use Camera Light&quot;">​</a></h5><p>Flash the back camera light during alerts (when the phone is charging).</p><div class="admonition xdripitem"><p class="admonition-title">Use Camera Light<img src="'+a+'" style="zoom:75%;"></p><p> Flash camera light during alerts when connected to a charger</p></div><h5 id="shortcut-to-bg-level-alerts" tabindex="-1">Shortcut to BG Level Alerts <a class="header-anchor" href="#shortcut-to-bg-level-alerts" aria-label="Permalink to &quot;Shortcut to BG Level Alerts&quot;">​</a></h5><p>You can add a shortcut entry to <code>Level Alerts</code> in xDrip main menu.</p><div class="admonition xdripitem"><p class="admonition-title">Shortcut to BG Level Alerts<img src="'+e+'" style="zoom:75%;"></p><p> Create a shortcut from main navigation to BG level screen</p></div><h5 id="suppress-alerts-if-missed-readings" tabindex="-1">Suppress alerts if missed readings <a class="header-anchor" href="#suppress-alerts-if-missed-readings" aria-label="Permalink to &quot;Suppress alerts if missed readings&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Suppress Alerts if missed readings</p></div><p>Level alerts remain active even if there is no signal (sensor change for example, or follower without network). This option allows you to suppress them. Make sure you have a missed alert enabled if you use this feature.</p><div class="admonition xdripitem"><p class="admonition-title">Suppress Alerts if missed readings <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Suppress snoozed and active alerts after predefined period of missed readings</p></div><p>You can define the number of minutes after which you want alerts to stop.</p><div class="admonition xdripitem"><p class="admonition-title">Suppress snoozed and active alerts after .. minutes (minimum 10)</p><p> Suppress snoozed and active alerts after predefined period of missed readings</p></div><h5 id="notification-channels" tabindex="-1">Notification Channels <a class="header-anchor" href="#notification-channels" aria-label="Permalink to &quot;Notification Channels&quot;">​</a></h5><p>Since Android 8.0 is now the minimum supported version, xDrip always uses Android notification channels for your alerts. The setting that used to enable them was removed when Android 7 support was retired (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12th Jul 2026</a>) — channels are now always active.</p><p>Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9th Sep 2026</a> xDrip only creates four channels, and plays alert sounds and vibration itself instead of through the channel. Older channels are removed automatically.</p><div class="admonition xdripitem"><p class="admonition-title">xDrip notification channels</p><p> Glucose level alerts<br>  Other alerts<br>  General<br>  Ongoing notification</p></div><p>The channel settings in Android Settings / Notifications / Apps / xDrip only decide whether the notification is displayed. Sound and vibration are governed by the xDrip settings: the <a href="#alert-volume-profile">alert volume profile</a>, and the Override silent mode and Vibrate on alert options of each alert. Turning a channel off hides the notification but does not silence the alert: disable the alert in xDrip instead.</p><h5 id="alert-priority" tabindex="-1">Alert priority <a class="header-anchor" href="#alert-priority" aria-label="Permalink to &quot;Alert priority&quot;">​</a></h5><p>Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9th Sep 2026</a>, when two alerts collide the more important one wins: it interrupts the sound and vibration of a less important alert already playing, and a less important alert cannot interrupt a more important one still sounding. This only affects sound and vibration, not snoozing or dismissing. From highest to lowest priority:</p><ol><li>Missed readings</li><li>Low glucose level</li><li>Persistent high</li><li>High glucose level</li><li>Forecasted low</li><li>BG falling or rising fast</li><li>Sensor expiry</li><li>BlueReader alarm</li><li>Bad (noisy) value alerts</li><li>Reminders</li><li>OB1 session restart</li><li>Other notifications</li></ol><p>Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.10.09" target="_blank" rel="noreferrer">9th Oct 2026</a>, when the phone is in silent mode (or the Silent <a href="#alert-volume-profile">alert volume profile</a> is selected) and Override silent mode is off, the alerts down to BG falling or rising fast still write a log entry saying no sound was played, so you can see afterwards that an alert was triggered.</p><h5 id="ascending-volume-settings" tabindex="-1">Ascending Volume settings <a class="header-anchor" href="#ascending-volume-settings" aria-label="Permalink to &quot;Ascending Volume settings&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Ascending Volume settings</p></div><h5 id="delay-ascending-volume" tabindex="-1">Delay Ascending Volume <a class="header-anchor" href="#delay-ascending-volume" aria-label="Permalink to &quot;Delay Ascending Volume&quot;">​</a></h5><p>You can delay the start of the ascending volume alert without delaying vibration that will start as soon as the alert is triggered.</p><div class="admonition xdripitem"><p class="admonition-title">Delay Ascending Volume<img src="'+t+'" style="zoom:75%;"></p><p> For ascending volume profile, delay the start of the alert sound by 3 minutes. The vibration (if enabled) starts as soon as the alert triggers regardless of this setting</p></div><h5 id="ascend-to-medium" tabindex="-1">Ascend to medium <a class="header-anchor" href="#ascend-to-medium" aria-label="Permalink to &quot;Ascend to medium&quot;">​</a></h5><p>You can limit the maximum volume of the ascending volume alerts and alarms to medium instead of maximum.</p><div class="admonition xdripitem"><p class="admonition-title">Ascend to medium<img src="'+e+'" style="zoom:75%;"></p><p> When enabled, ascending volume profile will ascend to medium volume instead of maximum</p></div><h3 id="calibration-alerts" tabindex="-1">Calibration Alerts <a class="header-anchor" href="#calibration-alerts" aria-label="Permalink to &quot;Calibration Alerts&quot;">​</a></h3><p>If your sensor requires periodic calibration you can set up xDrip to alert you when calibration is due.</p><p>You can set up the period between calibrations, sound to be played, etc.</p><div class="admonition xdrip"><p class="admonition-title">Calibration Alerts</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration Alerts<img src="'+a+'" style="zoom:75%;"></p><p> Alert when a calibration is requested</p></div><div class="admonition xdripitem"><p class="admonition-title">Hours between calibrations</p><p> How many hours between calibration requests</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration request sound</p><p> Default</p></div><div class="admonition xdripitem"><p class="admonition-title">Override Silent mode<img src="'+l+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Even when charging<img src="'+l+'" style="zoom:75%;"></p><p> Uncheck to not ask for calibrations when phone is charging</p></div><div class="admonition xdripitem"><p class="admonition-title">Repeat Alerts<img src="'+l+'" style="zoom:75%;"></p><p> Keep alerting if no calibration is performed</p></div><div class="admonition xdripitem"><p class="admonition-title">Alert Repeat minutes</p><p> 20</p></div><h5 id="initial-alert" tabindex="-1">Initial alert <a class="header-anchor" href="#initial-alert" aria-label="Permalink to &quot;Initial alert&quot;">​</a></h5><p>Initial calibration alert is used when starting a sensor requiring initial calibration: it will trigger when enough good readings are available to calibrate.</p><div class="admonition xdripitem"><p class="admonition-title">Initial Alert<img src="'+o+'" style="zoom:75%;"></p><p> Play sound when Initial Calibration is requested</p></div><h3 id="missed-reading-alert" tabindex="-1">Missed Reading Alert <a class="header-anchor" href="#missed-reading-alert" aria-label="Permalink to &quot;Missed Reading Alert&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Missed Reading Alert</p></div><p>When relying on xDrip to alert you for lows and highs, it is essential to make sure that it is actually receiving BG readings. For this, if you don&#39;t have any other alarms, enable this feature for your safety.</p><p>Setup is similar to <a href="#glucose-level-alerts-list">glucose level alerts</a>. <strong>The alarm sound has to be defined in Other Alerts</strong> (See <a href="#alert-preferences">below</a>). In order to test it, put your phone in airplane mode until it triggers.</p><div class="admonition xdrip"><p class="admonition-title">☰ Missed readings</p><p> <small>✅ Enable Missed Reading Alert</small><br>  <small>Alert if no data received in:</small><br>  <small><u> 30 </u> minutes</small><br>  <small>Select time for alert:</small><br>  <small>✅ all day</small></p><p> <small>Wait before raising the same alert after snooze:</small><br>  <small><u> 20 </u> minutes</small><br>  <small>☐ Reraise alerts before snooze time</small><br>  <small>Alert Reraise time:</small><br>  <small><u> 60 </u> seconds</small><br>  <small>☐ Override Silent Mode</small></p></div><h3 id="other-alerts" tabindex="-1">Other Alerts <a class="header-anchor" href="#other-alerts" aria-label="Permalink to &quot;Other Alerts&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Other Alerts</p></div><h4 id="noisy-readings" tabindex="-1">Noisy Readings <a class="header-anchor" href="#noisy-readings" aria-label="Permalink to &quot;Noisy Readings&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title"><small>NOISY READINGS</small></p></div><p>If you enable this feature and your sensor supports it, you can set up an alert for noisy readings.</p><div class="admonition xdripitem"><p class="admonition-title">Bad (noisy) Value Alerts<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Alert after x minutes of noisy values</p><p> 90</p></div><div class="admonition xdripitem"><p class="admonition-title">Alert snooze</p><p> Number of minutes before raising the same alert after snooze</p></div><div class="admonition xdripitem"><p class="admonition-title">Reraise alerts before snooze time<img src="'+e+'" style="zoom:75%;"></p><p> Reraise the alert if not snoozed sooner</p></div><div class="admonition xdripitem"><p class="admonition-title">Alert reraise time</p><p> Number of SECONDS to pass before raising the same alert.</p></div><h4 id="falling-or-rising-bg" tabindex="-1">Falling or rising BG <a class="header-anchor" href="#falling-or-rising-bg" aria-label="Permalink to &quot;Falling or rising BG&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title"><small>FALLING/RISING BG</small></p></div><p>You can also set up alerts for fast BG changes and define the 1 minute change triggering value. For example 3 per minute means 15 mg/dl (0.85 mmol/l) every 5 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">BG falling fast<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">falling rate threshold</p><p> 3 mg/dl/min (0.17 mmol/l/min)</p></div><div class="admonition xdripitem"><p class="admonition-title">BG rising fast<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">rising rate threshold</p><p> 3 mg/dl/min (0.17 mmol/l/min)</p></div><h5 id="alert-preferences" tabindex="-1">Alert preferences <a class="header-anchor" href="#alert-preferences" aria-label="Permalink to &quot;Alert preferences&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title"><small>ALERT PREFERENCES (FOR THESE ALERTS)</small></p></div><p>The alerts above and <strong>also Missed Readings</strong> use the sound and vibration defined below.<br> Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9th Sep 2026</a> xDrip plays them itself: the <a href="#notification-channels">notification channels</a> no longer control sound or vibration. The Vibrate only and Silent <a href="#alert-volume-profile">alert volume profiles</a> apply to these alerts too. When the phone is in vibrate mode only the vibration plays, and in silent mode nothing plays unless Override Silent mode is enabled.</p><div class="warning custom-block"><p class="custom-block-title">Make sure to test the alarm</p><p>This is an important feature to sleep safely. Reduce the missed readings period and put your phone in airplane mode (no Wi-Fi) to force the alarm to ring.</p></div><div class="admonition xdripitem"><p class="admonition-title">Alert sound</p><p> Default</p></div><p>Default is xDrip&#39;s own sound: the xDrip alarm for missed readings, a softer notification sound for the other alerts. Use CHOOSE FILE to pick a phone ringtone or your own file. Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.25" target="_blank" rel="noreferrer">25th Sep 2026</a> the softer sound is also used when the phone&#39;s <em>Default</em> ringtone is selected, including on installs upgraded from before 9th Sep 2026 that never changed this setting: unclear, rise, fall and similar alerts no longer sound like the glucose alarm.</p><div class="admonition xdripitem"><p class="admonition-title">Override Silent mode on these alerts<img src="'+t+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Vibrate on alert<img src="'+t+'" style="zoom:75%;"></p></div><h3 id="extra-alerts" tabindex="-1">Extra Alerts <a class="header-anchor" href="#extra-alerts" aria-label="Permalink to &quot;Extra Alerts&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Extra Alerts (xDrip)</p></div><h5 id="persistent-high-alert" tabindex="-1">Persistent High Alert <a class="header-anchor" href="#persistent-high-alert" aria-label="Permalink to &quot;Persistent High Alert&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Persistent High Alert</p></div><p>Instead of a high alert that will trigger as soon as BG reaches the trigger value, you can set up a persistent high alert that will only trigger when BG remains above a set value for more than a certain time. You can use either xDrip <a href="./settings.html#glucose-units">High Value</a> or a value you decide for triggering this alert.</p><div class="admonition xdripitem"><p class="admonition-title">Enable<img src="'+a+'" style="zoom:75%;"></p><p> Notify if above threshold for longer than the time specified below</p></div><div class="admonition xdripitem"><p class="admonition-title">Threshold: High Value<img src="'+o+'" style="zoom:75%;"></p><p> When enabled, High Value is the threshold.<br>  When disabled, the threshold is the value specified below.</p></div><div class="admonition xdripitem"><p class="admonition-title">Threshold</p><p> 170 mg/dl</p></div><div class="admonition xdripitem"><p class="admonition-title">for longer than (minutes)</p><p> 60</p></div><div class="admonition xdripitem"><p class="admonition-title">Repeating max every (minutes)</p><p> 20</p></div><div class="admonition xdripitem"><p class="admonition-title">Alert Sound</p><p> Choose the sound used for the alarm.</p></div><div class="admonition xdripitem"><p class="admonition-title">Override Silent Mode<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Vibrate on alert<img src="'+t+'" style="zoom:75%;"></p></div><h5 id="forecasted-low-alert" tabindex="-1">Forecasted Low Alert <a class="header-anchor" href="#forecasted-low-alert" aria-label="Permalink to &quot;Forecasted Low Alert&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Forecasted Low Alert</p></div><p>You can set an alarm on forecasted low value. This feature will use the <strong>momentum</strong> (extrapolation of the current BG trend) and <strong>not</strong> the <a href="./predictions.html">prediction</a> settings. Forecasted low (min) is the time in which a low will be forecasted (the one that usually displays in yellow on the graph screen).</p><p>Forecast Lows will display a message on xDrip screen. In order to have an alarm sound when a low is forecast, enable Raise alarm on Forecast Low.</p><div class="admonition xdripitem"><p class="admonition-title">Forecast Lows<img src="'+o+'" style="zoom:75%;"></p><p> Considering the current value and trend, calculate what the next few readings will be if the trend persists (extrapolate). This ignores insulin or carbs on board.</p></div><div class="admonition xdripitem"><p class="admonition-title">Raise alarm on Forecast Low<img src="'+e+'" style="zoom:75%;"></p><p> Notify when forecasted low time reaches time threshold</p></div><div class="admonition xdripitem"><p class="admonition-title">Threshold: Low Value<img src="'+o+'" style="zoom:75%;"></p><p> When enabled, Low Value is the threshold.<br>  When disabled, the threshold is the value specified below.</p></div><div class="admonition xdripitem"><p class="admonition-title">Threshold</p><p> 70 mg/dl</p></div><div class="admonition xdripitem"><p class="admonition-title">Time threshold [min]</p><p> 40</p></div><div class="admonition xdripitem"><p class="admonition-title">Alert Sound</p><p> Choose the sound used for the alarm.</p></div><div class="admonition xdripitem"><p class="admonition-title">Override Silent Mode<img src="'+e+'" style="zoom:75%;"></p></div><div class="admonition xdripitem"><p class="admonition-title">Vibrate on alert<img src="'+t+'" style="zoom:75%;"></p></div><p>In the example below if you set Alarm at forecasted low (min) to 50 minutes, it will trigger. The red dotted line is the forecasted BG trend, extrapolated from the previous measurements.</p><img src="'+f+'" style="zoom:75%;"><h5 id="sensor-expiry-notifications" tabindex="-1">Sensor Expiry Notifications <a class="header-anchor" href="#sensor-expiry-notifications" aria-label="Permalink to &quot;Sensor Expiry Notifications&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Sensor Expiry Notifications</p><p> Raise notifications when the sensor gets close to expiry.</p></div><div class="admonition xdripitem"><p class="admonition-title">Enable<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Raise notifications when the sensor gets close to expiry.</p></div><p>Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9th Sep 2026</a> a follower shows the same notification when the master&#39;s expiry warning arrives, provided this setting is also enabled on the follower and treatments are synchronized from the master. The warning is shown once per sensor warning and ignored if it reaches the follower more than 30 minutes late.</p><h5 id="follower-chime-new" tabindex="-1">Follower Chime New <a class="header-anchor" href="#follower-chime-new" aria-label="Permalink to &quot;Follower Chime New&quot;">​</a></h5><p>After missed readings, a notification will sound when new data is received after more than 20 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Follower Chime New<img src="'+a+'" style="zoom:75%;"></p><p> Notify when data arrives from the master if the interval is &gt; 20 mins.</p></div><h2 id="snooze-alert" tabindex="-1">Snooze Alert <a class="header-anchor" href="#snooze-alert" aria-label="Permalink to &quot;Snooze Alert&quot;">​</a></h2><div class="admonition xdrip"><p class="admonition-title"><img src="'+p+'" style="zoom:75%;"></p><p> Snooze Alert</p></div><p>If there is no active alert, you can <strong>pre-snooze</strong> alerts from this menu so that they won&#39;t trigger for a certain time.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Snooze</p><div style="text-align:center;"> No active alert exists</div><div style="background-color:gray;color:white;text-align:center;">  Disable Low Alerts </div><div style="background-color:gray;color:white;text-align:center;">  Disable High Alerts </div><div style="background-color:gray;color:white;text-align:center;">  Disable All Alerts </div></div><p>You will be proposed a default snooze period. Scroll up and down to change it.</p><div class="admonition xdrip"><p class="admonition-title">Default Snooze</p><div style="background-color:darkgray;color:dimgray;text-align:center;">  50 minutes </div><div style="background-color:darkgray;color:black;text-align:center;">  60 minutes </div><div style="background-color:darkgray;color:dimgray;text-align:center;">  70 minutes </div></div><p>If an alert triggers you will see the notification in your phone drop down panel, and possibly hear the sound.</p><p>You can snooze the alert by swiping the notification, you can customize it further by tapping it.</p><img src="'+v+'" style="zoom:75%;"><p>You can access the snooze menu by touching the notification or from xDrip main menu, snooze alert.</p><p>At this point, the snooze menu will also display the active alert.<br> Touching snooze will snooze it for the period selected.</p>',185)),s("div",T,[i[1]||(i[1]=s("p",{class:"admonition-title"},[s("img",{src:n,style:{zoom:"75%"}}),m("Snooze")],-1)),s("div",L,[c(d,null,{default:h(()=>[c(d,null,{default:h(()=>[...i[0]||(i[0]=[m("Snooze",-1)])]),_:1})]),_:1})]),i[2]||(i[2]=r('<div style="background-color:dimgray;color:white;text-align:center;">  <div style="background-color:black;color:dimgray;text-align:center;">  20 minutes </div><div style="background-color:black;color:darkgray;text-align:center;">  30 minutes </div><div style="background-color:black;color:dimgray;text-align:center;">  40 minutes </div></div><p>Active alert exists named &quot;Night&quot; Alert will rerise at 1:25:01 (0 minutes left)</p><div style="background-color:dimgray;color:white;text-align:center;">  Disable Low Alerts </div><div style="background-color:dimgray;color:white;text-align:center;">  Disable High Alerts </div><div style="background-color:dimgray;color:white;text-align:center;">  Disable All Alerts </div>',5))]),i[4]||(i[4]=r('<h5 id="all-alerts-currently-disabled" tabindex="-1">ALL ALERTS CURRENTLY DISABLED <a class="header-anchor" href="#all-alerts-currently-disabled" aria-label="Permalink to &quot;ALL ALERTS CURRENTLY DISABLED&quot;">​</a></h5><p>If you pre-snooze (disable) all alerts, you will see this warning message.</p><img src="'+b+'" style="zoom:75%;"><p>To remove it you need to re-enable alerts.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Snooze</p><div style="text-align:center;"> All alerts disabled until 15:09:12</div><div style="background-color:gray;color:white;text-align:center;">  Re-Enable All Alerts </div></div><br><h2 id="visible-alert-notification" tabindex="-1">Visible alert notification <a class="header-anchor" href="#visible-alert-notification" aria-label="Permalink to &quot;Visible alert notification&quot;">​</a></h2><p>Available for Android 8 and above.</p><p>When an alert triggers you will see it in the notifications drop down panel.</p><img src="'+y+'" style="zoom:75%;"><p>Swiping it will snooze it, touching it will open a preferences menu.<br> Deliver quietly only affects the Android notification itself. Since <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9th Sep 2026</a> the alert sound and vibration are played by xDrip and follow the xDrip alert settings, not the <a href="#notification-channels">notification channel</a>.</p><img src="'+w+'" style="zoom:75%;"><p>You can switch back to alerting delivery from the same menu.</p><img src="'+x+'" style="zoom:75%;"><p>Settings will drive you to your phone notifications setup settings.</p><img src="'+A+'" style="zoom:75%;"><p>You can also completely turn off <a href="#notification-channels">notification channels</a> for xDrip. This hides the notifications but does not stop the alert sound.</p><img src="'+k+'" style="zoom:75%;"><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',19))])}const U=S(D,[["render",E]]);export{W as __pageData,U as default};
